'use strict';

// MODULES //

var reinterpret = require( '@stdlib/strided/base/reinterpret-complex64' );
var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Performs the hermitian rank 2 operation `A = alpha*x*y**H + conjg( alpha )*y*x**H + A`, where `alpha` is a scalar, `x` and `y` are `N` element vectors and `A` is an `N` by `N` hermitian matrix.
*
* @private
* @param {string} uplo - specifies whether `A` is an upper or lower triangular part of matrix is supplied.
* @param {NonNegativeInteger} N - number of elements along each dimension of `A`
* @param {Complex64} alpha - scalar
* @param {Complex64Array} x - first input array
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting `x` index
* @param {Complex64Array} y - second input array
* @param {integer} strideY - `y` stride length
* @param {NonNegativeInteger} offsetY - starting `y` index
* @param {Complex64Array} A - input matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @returns {Complex64Array} `A`
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var Complex64 = require( '@stdlib/complex/float32/ctor' );
*
* var x = new Complex64Array( [ 1.0, 1.0, 1.0, 1.0 ] );
* var y = new Complex64Array( [ 1.0, 1.0, 1.0, 1.0 ] );
* var A = new Complex64Array( [ 1.0, 0.0, 0.0, 0.0, 2.0, 3.0, 4.0, 0.0 ] );
* var alpha = new Complex64( 1.0, 0.0 );
*
* cher2( 'lower', x.length, alpha, x, 1, 0, y, 1, 0, A, 2, 1, 0 );
* // A => <Complex64Array>[ 5.0, 0.0, 0.0, 0.0, 6.0, 3.0, 8.0, 0.0 ]
*/
function cher2( uplo, N, alpha, x, strideX, offsetX, y, strideY, offsetY, A, strideA1, strideA2, offsetA ) {
    var alpha_re;
    var alpha_im;
    var tmp1_re;
    var tmp1_im;
    var tmp2_re;
    var tmp2_im;
    var re0_x;
    var im0_x;
    var re0_y;
    var im0_y;
    var re1_x;
    var im1_x;
    var re1_y;
    var im1_y;
	var viewX;
    var viewY;
    var viewA;
    var isrm;
    var idx;
    var ix1;
    var iy1;
    var ix0;
    var iy0;
    var re0;
    var im0;
    var re1;
    var im1;
    var sa0;
    var sa1;
    var re;
    var im;
    var i1;
    var i0;
    var ix;
    var iy;
    var ia;
    var sx;
    var sy;

    alpha_re = f32( alpha.re );
    alpha_im = f32( alpha.im );

    viewX = reinterpret( x, 0 );
    viewY = reinterpret( y, 0 );
    viewA = reinterpret( A, 0 );

    isrm = isRowMajor( [ strideA1, strideA2 ] );
    if ( isrm ) {
        sa0 = strideA2 * 2;
        sa1 = strideA1 * 2;
    } else {
        sa0 = strideA1 * 2;
        sa1 = strideA2 * 2;
    }
    ix = offsetX * 2;
    iy = offsetY * 2;
    ia = offsetA * 2;
    sx = strideX * 2;
    sy = strideY * 2;
    if ( ( isrm && uplo === 'upper' ) || ( !isrm && uplo === 'lower' ) ) {
        for ( i1 = 0; i1 < N; i1++ ) {
            ix1 = ix + ( i1 * sx );
            iy1 = iy + ( i1 * sy );
            re0_x = f32( viewX[ ix1 ] );
            im0_x = f32( viewX[ ix1 + 1 ] );
            re0_y = f32( viewY[ iy1 ] );
            im0_y = f32( viewY[ iy1 + 1 ] );
            for ( i0 = i1; i0 < N; i0++ ) {
                ix0 = ix + ( i0 * sx );
                iy0 = iy + ( i0 * sy );
                re1_x = f32( viewX[ ix0 ] );
                im1_x = f32( viewX[ ix0 + 1 ] );
                re1_y = f32( viewY[ iy0 ] );
                im1_y = f32( viewY[ iy0 + 1 ] );

                re0 = f32( ( re0_x * re1_y ) + ( im0_x * im1_y ) );
                im0 = f32( ( im0_x * re1_y ) - ( re0_x * im1_y ) );
                tmp1_re = f32( ( alpha_re * re0 ) - ( alpha_im * im0 ) );
                tmp1_im = f32( ( alpha_re * im0 ) + ( alpha_im * re0 ) );

                re1 = f32( ( re0_y * re1_x ) + ( im0_y * im1_x ) );
                im1 = f32( ( im0_y * re1_x ) - ( re0_y * im1_x ) );
                tmp2_re = f32( ( alpha_re * re1 ) + ( alpha_im * im1 ) );
                tmp2_im = f32( ( alpha_re * im1 ) - ( alpha_im * re1 ) );

                re = f32( tmp1_re + tmp2_re );
                im = f32( tmp1_im + tmp2_im );
                idx = ia + ( i0 * sa0 ) + ( i1 * sa1 );
                viewA[ idx ] =  f32( viewA[ idx ] + re );
                viewA[ idx + 1 ] = f32( viewA[ idx + 1 ] + im );
                if ( i0 === i1 ) {
                    viewA[ idx + 1 ] = 0.0;
                }
            }
        }
        return A;
    }
    // ( isrm && uplo === 'lower' ) || ( !isrm && uplo === 'upper' )
    for ( i1 = 0; i1 < N; i1++ ) {
        ix1 = ix + ( i1 * sx );
        iy1 = iy + ( i1 * sy );
        re0_x = f32( viewX[ ix1 ] );
        im0_x = f32( viewX[ ix1 + 1 ] );
        re0_y = f32( viewY[ iy1 ] );
        im0_y = f32( viewY[ iy1 + 1 ] );
        for ( i0 = 0; i0 <= i1; i0++ ) {
            ix0 = ix + ( i0 * sx );
            iy0 = iy + ( i0 * sy );
            re1_x = f32( viewX[ ix0 ] );
            im1_x = f32( viewX[ ix0 + 1 ] );
            re1_y = f32( viewY[ iy0 ] );
            im1_y = f32( viewY[ iy0 + 1 ] );

            re0 = f32( ( re0_x * re1_y ) + ( im0_x * im1_y ) );
            im0 = f32( ( im0_x * re1_y ) - ( re0_x * im1_y ) );
            tmp1_re = f32( ( alpha_re * re0 ) - ( alpha_im * im0 ) );
            tmp1_im = f32( ( alpha_re * im0 ) + ( alpha_im * re0 ) );

            re1 = f32( ( re0_y * re1_x ) + ( im0_y * im1_x ) );
            im1 = f32( ( im0_y * re1_x ) - ( re0_y * im1_x ) );
            tmp2_re = f32( ( alpha_re * re1 ) + ( alpha_im * im1 ) );
            tmp2_im = f32( ( alpha_re * im1 ) - ( alpha_im * re1 ) );

            re = f32( tmp1_re + tmp2_re );
            im = f32( tmp1_im + tmp2_im );
            idx = ia + ( i0 * sa0 ) + ( i1 * sa1 );
            viewA[ idx ] =  f32( viewA[ idx ] + re );
            viewA[ idx + 1 ] = f32( viewA[ idx + 1 ] + im );
            if ( i0 === i1 ) {
                viewA[ idx + 1 ] = 0.0;
            }
        }
    }
    return A;
}


// EXPORTS //

module.exports = cher2;
